/**
 * Types for the OpenNext worker bundle (`.open-next/worker.js`, generated by
 * `opennextjs-cloudflare build`). worker.ts imports it as "open-next-worker" (tsconfig paths).
 */
declare module "open-next-worker" {
  const handler: {
    fetch: (request: Request, env: CloudflareEnv, ctx: ExecutionContext) => Promise<Response>;
  };
  export default handler;
  export class DOQueueHandler {}
  export class DOShardedTagCache {}
  export class BucketCachePurge {}
}
